// Extract-from-File returns the whole array on one item; split it
// into one item per session so every downstream node works per session.
const first = $input.first().json;
const sessions = Array.isArray(first) ? first : (first.sessions ?? first.data ?? []);
return sessions.map((session) => ({ json: session }));

// Bounded sampler: first 40 turns + last 20 turns of each transcript.
// Turns are de-duplicated by their original index, so a short transcript
// (fewer than 60 turns) is returned whole and in order, never doubled.
const HEAD_TURNS = 40;
const TAIL_TURNS = 20;

const output = [];

for (const item of $input.all()) {
  const session = item.json;
  const turns = Array.isArray(session.transcript) ? session.transcript : [];

  const seenIndexes = new Set();
  const sample = [];
  const addTurn = (turn, index) => {
    if (seenIndexes.has(index)) return;
    seenIndexes.add(index);
    sample.push(turn);
  };

  turns.slice(0, HEAD_TURNS).forEach((turn, i) => addTurn(turn, i));

  const tailStart = Math.max(0, turns.length - TAIL_TURNS);
  turns.slice(tailStart).forEach((turn, i) => addTurn(turn, tailStart + i));

  output.push({
    json: {
      session_id: session.id,
      title: session.title ?? '',
      created_at: session.created_at ?? null,
      participants: session.participants ?? [],
      total_turns: turns.length,
      sampled_turns: sample.length,
      sample,
      // The full transcript travels with the item: the dual-stream parser
      // downstream needs every turn, not just the classification sample.
      transcript: turns,
    },
  });
}

return output;

// Safely parse the classifier reply. This node must never crash the run:
// any unparseable or out-of-vocabulary answer degrades to Other / 0.0,
// which the Switch downstream routes to the archive, never to the vault.
const VALID_TYPES = ['Client Coaching', 'Internal Operations', 'Sales Discovery', 'Other'];

function extractText(json) {
  if (json == null) return '';
  if (typeof json === 'string') return json;
  if (Array.isArray(json.choices) && json.choices[0]?.message?.content) {
    return json.choices[0].message.content; // OpenAI-compatible chat response
  }
  if (json.message?.content) return json.message.content; // Ollama chat response
  if (typeof json.response === 'string') return json.response;
  if (json.meeting_type) return JSON.stringify(json); // already structured
  return '';
}

function parseClassification(rawText) {
  const cleaned = String(rawText).replace(/```(?:json)?/gi, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try {
    return JSON.parse(cleaned.slice(start, end + 1));
  } catch {
    return null;
  }
}

const samplerItems = $('Bounded Sampler').all();

return $input.all().map((item, index) => {
  const session = samplerItems[index]?.json ?? {};
  const parsed = parseClassification(extractText(item.json));

  const isValid = parsed && VALID_TYPES.includes(parsed.meeting_type);
  const rawConfidence = isValid ? Number(parsed.confidence_score) : 0;

  const classification = {
    meeting_type: isValid ? parsed.meeting_type : 'Other',
    confidence_score: Number.isFinite(rawConfidence)
      ? Math.min(1, Math.max(0, rawConfidence))
      : 0,
    summary: isValid && typeof parsed.summary === 'string' ? parsed.summary : '',
  };

  return {
    json: {
      session_id: session.session_id,
      title: session.title ?? '',
      participants: session.participants ?? [],
      transcript: session.transcript ?? [],
      classification,
    },
    pairedItem: { item: index },
  };
});

// Dual-stream parser for approved coaching sessions.
//   framework    -> one dense, extractive takeaway built from the coach's
//                   substantive turns (the concepts worth retrieving).
//   voice_sample -> ONLY the coach's verbatim turns, chunked to 400-700
//                   characters on turn boundaries (the tone worth mirroring).
// The coach is the team-member participant (Dr. Sara Hegy in the mock data);
// client turns never enter either stream.
const MIN_CHUNK_CHARS = 400;
const MAX_CHUNK_CHARS = 700;
const MIN_FRAMEWORK_TURN_CHARS = 150;

function chunkTurns(turns) {
  const chunks = [];
  let buffer = '';
  for (const turn of turns) {
    const text = (turn.text ?? '').trim();
    if (!text) continue;
    const candidate = buffer ? `${buffer} ${text}` : text;
    if (candidate.length > MAX_CHUNK_CHARS && buffer.length >= MIN_CHUNK_CHARS) {
      chunks.push(buffer);
      buffer = text;
    } else {
      buffer = candidate;
    }
  }
  if (buffer) chunks.push(buffer); // final remainder may be under 400 chars
  return chunks;
}

const output = [];

for (const item of $input.all()) {
  const { session_id, title, participants, transcript, classification } = item.json;

  const coach = (participants ?? []).find((p) => p.is_team_member);
  const coachName = coach?.name;
  if (!coachName) continue;

  const coachTurns = (transcript ?? []).filter((t) => t.speaker === coachName);

  const frameworkText = coachTurns
    .filter((t) => (t.text ?? '').trim().length >= MIN_FRAMEWORK_TURN_CHARS)
    .map((t) => t.text.trim())
    .join(' ');

  if (frameworkText) {
    output.push({
      json: {
        session_id,
        stream_type: 'framework',
        content: frameworkText,
        metadata: {
          title: title ?? '',
          coach: coachName,
          source: 'extractive_dense_coach_turns',
          classifier_confidence: classification?.confidence_score ?? null,
        },
      },
    });
  }

  chunkTurns(coachTurns).forEach((content, chunkIndex) => {
    output.push({
      json: {
        session_id,
        stream_type: 'voice_sample',
        content,
        metadata: {
          title: title ?? '',
          coach: coachName,
          chunk_index: chunkIndex,
          char_count: content.length,
        },
      },
    });
  });
}

return output;

// Join each chunk back to its embedding response (the embedding HTTP node
// replaces the item JSON, so the chunk fields are read from the parser node,
// paired by item order) and format the vector as a pgvector literal.
const parserItems = $('Dual-Stream Parser').all();

function extractEmbedding(json) {
  if (Array.isArray(json?.data?.[0]?.embedding)) return json.data[0].embedding; // OpenAI-compatible
  if (Array.isArray(json?.embeddings?.[0])) return json.embeddings[0]; // Ollama native
  if (Array.isArray(json?.embedding)) return json.embedding;
  return null;
}

const output = [];

$input.all().forEach((item, index) => {
  const chunk = parserItems[index]?.json;
  const embedding = extractEmbedding(item.json);
  if (!chunk || !embedding) return; // never insert a row without a vector
  output.push({
    json: {
      session_id: chunk.session_id,
      stream_type: chunk.stream_type,
      content: chunk.content,
      metadata: chunk.metadata,
      embedding_literal: `[${embedding.join(',')}]`,
      embedding_dims: embedding.length,
    },
    pairedItem: { item: index },
  });
});

return output;
